WITH department_summary AS (SELECT dept_id, ROUND((100 * SUM(CASE WHEN job_title = 'Manager' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_manager, COUNT(*) AS employee_count FROM employees WHERE dept_id = 16 GROUP BY dept_id) SELECT d.id, d.budget, ds.pct_manager, ds.employee_count FROM departments d INNER JOIN department_summary ds ON d.id = ds.dept_id WHERE ds.pct_manager > 24 ORDER BY budget ASC;
